window.StudioEvents=function(event){var d=event.data||{};switch(event.type){
 case 'reply':var entry=pending.get(d.request);if(entry){clearTimeout(entry.timer);pending.delete(d.request);if(d.error)entry.reject(new Error(d.error));else entry.resolve(d.value);}break;
 case 'boot':if(d.screen==='settings')navigate('settings');else if(d.selection){recordId=d.selection;poll(true);}else poll(true);break;
 case 'open':openMeeting(d.id);break;
 case 'videoLink':videoSheet(d.url);break;
 case 'navigate':if(d.screen==='settings')navigate('settings');else navigate('library');break;
 case 'resume':viewActive=true;schedule();if(screen==='settings')loadSettings(false);break;
 case 'visibility':viewActive=!!d.visible;schedule();break;
 case 'pulse':{
  var wasRecording=recording;recording=!!d.recording||recording&&Date.now()<startingUntil;paused=!!d.paused;if(d.id)recordId=d.id;if(recording)recordSamples=d.samples||0;waveHistory.shift();waveHistory.push(paused?0:Math.max(0,Math.min(1,d.level||0)));if(!$('recordingScreen').hidden){cancelAnimationFrame(waveFrame);waveFrame=requestAnimationFrame(drawWave);}
  if(d.playerId===selected){position=d.position||0;duration=d.duration||duration;playing=!!d.playing;renderPlayer();var next=null;if(playing){var lo=0,hi=turns.length-1,best=-1;while(lo<=hi){var mid=(lo+hi)>>1;if(turns[mid].start<=position){best=mid;lo=mid+1;}else hi=mid-1;}if(best>=0&&position<turns[best].end)next=turnNodes.get(turns[best].index);}if(next!==highlightedTurn){if(highlightedTurn)highlightedTurn.classList.remove('is-playing');if(next)next.classList.add('is-playing');highlightedTurn=next;}}
  else if(!d.playing&&playing){playing=false;renderPlayer();}updateRecordUI();if(wasRecording&&!recording){libraryKey='';setTimeout(function(){poll(true);},150);}break;
 }
 case 'playbackEnd':playing=false;position=duration;renderPlayer();break;
 case 'error':toast(d.message,true);break;
 case 'toast':toast(d.message);break;
 case 'configChanged':settingsKey='';loadSettings(true);break;
 case 'importProgress':var status=$('runtimeStatus');if(status)status.textContent='Добавляем модель · '+bytes(d.done)+(d.total>0?' из '+bytes(d.total):'');break;
 }};
